# Terraform Module: S3 Bucket + RDS PostgreSQL + IAM

Here's a complete, production-ready Terraform module implementing the specification.

## Directory Structure

```
.
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── s3.tf
│       ├── rds.tf
│       ├── iam.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
└── backend.tf
```

---

## Module: `modules/app-infra/`

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.0"
      configuration_aliases = [aws.replica]
    }
  }
}
```

### `variables.tf`

```hcl
variable "environment" {
  description = "Deployment environment (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be 'dev' or 'prod'."
  }
}

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---- S3 ----
variable "enable_cross_region_replication" {
  description = "Enable S3 cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Destination region for S3 replication"
  type        = string
  default     = "us-west-2"
}

# ---- RDS ----
variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage"
  type        = bool
  default     = true
}

variable "db_allocated_storage" {
  description = "Allocated storage (GB)"
  type        = number
  default     = 20
}

variable "db_backup_retention_days" {
  description = "Backup retention in days (must be >= 7)"
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days."
  }
}

variable "db_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "16.3"
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master DB username"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master DB password (injected via -var-file / SOPS, never committed)"
  type        = string
  sensitive   = true
}

variable "vpc_id" {
  description = "VPC ID for RDS/security groups"
  type        = string
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group"
  type        = list(string)
}

variable "db_ingress_cidrs" {
  description = "CIDRs allowed to reach the DB port"
  type        = list(string)
  default     = []
}

# ---- IAM ----
variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA (prod least-privilege trust)"
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "EKS OIDC provider URL (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "Kubernetes namespace of the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name"
  type        = string
  default     = "app-sa"
}
```

### `main.tf`

```hcl
locals {
  common_tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
    Module      = "app-infra"
  })

  bucket_name = "${var.name_prefix}-${var.environment}-assets"
  db_id       = "${var.name_prefix}-${var.environment}-pg"
}

data "aws_caller_identity" "current" {}
```

### `s3.tf`

```hcl
# ---------------------------------------------------------------------------
# Primary application assets bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "assets" {
  bucket = local.bucket_name
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

# No public access
resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Cross-region replication (prod only)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  count    = var.enable_cross_region_replication ? 1 : 0
  provider = aws.replica

  bucket = "${local.bucket_name}-replica"
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_cross_region_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_cross_region_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_cross_region_replication ? 1 : 0
  provider = aws.replica

  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${local.bucket_name}-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${local.bucket_name}-replication"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.assets.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.assets.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_cross_region_replication ? 1 : 0

  # Replication requires versioning enabled on source
  depends_on = [aws_s3_bucket_versioning.assets]

  role   = aws_iam_role.replication[0].arn
  bucket = aws_s3_bucket.assets.id

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}
```

### `rds.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${local.db_id}-subnet-group"
  subnet_ids = var.db_subnet_ids
  tags       = local.common_tags
}

resource "aws_security_group" "rds" {
  name        = "${local.db_id}-sg"
  description = "RDS PostgreSQL access"
  vpc_id      = var.vpc_id
  tags        = local.common_tags

  ingress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.db_ingress_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres" {
  identifier     = local.db_id
  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  allocated_storage = var.db_allocated_storage
  storage_type      = "gp3"
  storage_encrypted = var.db_storage_encrypted

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  # Acceptance criteria
  multi_az                = var.db_multi_az
  deletion_protection     = true
  publicly_accessible     = false
  backup_retention_period = var.db_backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  auto_minor_version_upgrade  = true
  copy_tags_to_snapshot       = true
  skip_final_snapshot         = false
  final_snapshot_identifier   = "${local.db_id}-final"
  apply_immediately           = false
  performance_insights_enabled = var.environment == "prod"

  tags = local.common_tags

  lifecycle {
    ignore_changes = [password]
  }
}
```

### `iam.tf`

```hcl
# ---------------------------------------------------------------------------
# DEV: IAM user with programmatic access (scoped to the bucket)
# ---------------------------------------------------------------------------
resource "aws_iam_user" "service" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${var.name_prefix}-${var.environment}-svc"
  tags  = local.common_tags
}

resource "aws_iam_access_key" "service" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.service[0].name
}

resource "aws_iam_user_policy" "service" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${var.name_prefix}-${var.environment}-svc-policy"
  user  = aws_iam_user.service[0].name

  policy = data.aws_iam_policy_document.app_permissions.json
}

# ---------------------------------------------------------------------------
# PROD: IAM role with OIDC (IRSA) trust — least privilege
# ---------------------------------------------------------------------------
resource "aws_iam_role" "service" {
  count = var.environment == "prod" ? 1 : 0
  name  = "${var.name_prefix}-${var.environment}-svc-role"
  tags  = local.common_tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${var.oidc_provider_url}:sub" = "system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"
          "${var.oidc_provider_url}:aud" = "sts.amazonaws.com"
        }
      }
    }]
  })
}

resource "aws_iam_role_policy" "service" {
  count  = var.environment == "prod" ? 1 : 0
  name   = "${var.name_prefix}-${var.environment}-svc-policy"
  role   = aws_iam_role.service[0].id
  policy = data.aws_iam_policy_document.app_permissions.json
}

# ---------------------------------------------------------------------------
# Shared least-privilege policy — explicit actions, NO wildcards
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "app_permissions" {
  # S3 object-level access, scoped to this bucket
  statement {
    sid    = "BucketObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid    = "BucketListAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [aws_s3_bucket.assets.arn]
  }
}
```

### `outputs.tf`

```hcl
output "bucket_name" {
  description = "Name of the primary assets bucket"
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  description = "ARN of the primary assets bucket"
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_arn" {
  description = "ARN of the replica bucket (prod only)"
  value       = try(aws_s3_bucket.replica[0].arn, null)
}

output "db_endpoint" {
  description = "RDS connection endpoint"
  value       = aws_db_instance.postgres.endpoint
}

output "db_identifier" {
  description = "RDS instance identifier"
  value       = aws_db_instance.postgres.id
}

output "service_role_arn" {
  description = "IAM role ARN (prod) for the service account"
  value       = try(aws_iam_role.service[0].arn, null)
}

output "service_user_name" {
  description = "IAM user name (dev)"
  value       = try(aws_iam_user.service[0].name, null)
}

output "service_access_key_id" {
  description = "Access key ID (dev only)"
  value       = try(aws_iam_access_key.service[0].id, null)
  sensitive   = true
}

output "service_secret_access_key" {
  description = "Secret access key (dev only)"
  value       = try(aws_iam_access_key.service[0].secret, null)
  sensitive   = true
}
```

