## Root Configuration

### `providers.tf`

```hcl
provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Project = "canonical-scenario"
    }
  }
}

# Alias provider for cross-region replication destination
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}
```

### `backend.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  # Per-workspace state isolation:
  # State keys become env:/<workspace>/<key>, so dev and prod
  # never share state. Changing prod cannot modify dev.
  backend "s3" {
    bucket         = "my-org-terraform-state"
    key            = "app-infra/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

