## Environment tfvars

### `environments/dev.tfvars`

```hcl
environment       = "dev"
region            = "us-east-1"
name_prefix       = "canonical"

# RDS — dev sizing
db_instance_class        = "db.t3.micro"
db_multi_az              = false
db_storage_encrypted     = true
db_backup_retention_days = 7

# S3 — no replication in dev
enable_cross_region_replication = false

# Network (replace with real values)
vpc_id           = "vpc-xxxxxxxx"
db_subnet_ids    = ["subnet-aaa", "subnet-bbb"]
db_ingress_cidrs = ["10.0.0.0/16"]

# db_password is NOT here — injected via SOPS-decrypted file (see below)
```

### `environments/prod.tfvars`

```hcl
environment       = "prod"
region            = "us-east-1"
replica_region    = "us-west-2"
name_prefix       = "canonical"

# RDS — prod sizing
db_instance_class        = "db.t3.medium"
db_multi_az              = true
db_storage_encrypted     = true
db_backup_retention_days = 14

# S3 — cross-region replication to us-west-2
enable_cross_region_replication = true

# Network (replace with real values)
vpc_id           = "vpc-yyyyyyyy"
db_subnet_ids    = ["subnet-ccc", "subnet-ddd"]
db_ingress_cidrs = ["10.1.0.0/16"]

# IRSA / OIDC trust — least privilege, no static keys
oidc_provider_arn = "arn:aws:iam::111122223333:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
oidc_provider_url = "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
```

